customCSS:
:root {
 --background:var(--lc-hermes-canvas,#0d0d0d)!important; --background-base:var(--lc-hermes-canvas,#0d0d0d)!important;
 --midground:var(--lc-hermes-text,#ececec)!important; --midground-base:var(--lc-hermes-text,#ececec)!important;
 --color-text-primary:var(--lc-hermes-text,#ececec)!important; --color-text-secondary:var(--lc-hermes-muted,#cdcdcd)!important;
 --color-card:var(--lc-hermes-panel,#171717)!important; --color-popover:var(--lc-hermes-panel,#171717)!important;
 --color-card-foreground:var(--lc-hermes-text,#ececec)!important; --color-popover-foreground:var(--lc-hermes-text,#ececec)!important;
 --color-secondary:var(--lc-hermes-control,#212121)!important; --color-accent:var(--lc-hermes-hover,#2f2f2f)!important;
 --color-muted:var(--lc-hermes-control,#212121)!important; --color-muted-foreground:var(--lc-hermes-muted,#cdcdcd)!important;
 --color-primary:var(--lc-hermes-text,#ececec)!important; --color-primary-foreground:var(--lc-hermes-canvas,#0d0d0d)!important;
 --color-secondary-foreground:var(--lc-hermes-text,#ececec)!important; --color-accent-foreground:var(--lc-hermes-text,#ececec)!important;
 --color-border:var(--lc-hermes-border,#393939)!important; --color-input:var(--lc-hermes-border,#393939)!important;
 --color-ring:var(--lc-hermes-muted,#cdcdcd)!important;
 --theme-font-sans:var(--lc-hermes-font,Inter,system-ui,-apple-system,"Segoe UI",sans-serif)!important;
 --theme-font-display:var(--theme-font-sans)!important; --font-sans:var(--theme-font-sans)!important;
 --theme-base-size:14px!important; --theme-line-height:1.5!important; --theme-letter-spacing:0!important;
 --theme-radius:12px!important; --radius:12px!important;
 --component-card-border-radius:12px; --component-card-background:var(--color-card);
 --component-header-background:var(--background-base); --component-page-background:var(--background-base);
}
body { color:var(--midground); background:var(--background-base); }
:where(h1,h2,h3,h4,legend,label,button,input,textarea,select,nav,[role="tab"],[role="menuitem"],.font-expanded,.font-compressed,.font-mondwest,.font-sans) {
 font-family:var(--theme-font-sans)!important; letter-spacing:normal!important;
}
:where(h1,h2,h3,h4) { font-weight:600!important; line-height:1.4!important; }
h1 { font-size:1.125rem!important; } h2 { font-size:1rem!important; }
button,[role="button"] { border-radius:9px; text-transform:none!important; font-weight:500!important; line-height:1.35!important; box-shadow:none!important; }
button[class*="shadow-"] { border:1px solid var(--color-border); }
button:disabled { cursor:not-allowed; }
button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,[role="tab"]:focus-visible { outline:2px solid var(--color-ring); outline-offset:2px; }
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),textarea,select { border-radius:9px; background-color:var(--color-secondary); color:var(--midground); }
input::placeholder,textarea::placeholder { color:var(--color-muted-foreground); }
[data-slot="card"], [class~="bg-card"][class~="border"], [role="dialog"], [role="menu"] { border-radius:12px; }
[class~="font-mono"]:not(pre):not(code):not(kbd):not(samp),.font-mono-ui { font-family:var(--theme-font-sans); letter-spacing:normal; }
pre,code,kbd,samp,.xterm,.xterm * { font-family:var(--theme-font-mono,ui-monospace,SFMono-Regular,Consolas,monospace)!important; }
@media (prefers-reduced-motion:reduce) { button,input,select { transition:none!important; } }
